+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.core.ui.MainLayout;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H2;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.data.provider.Query;
+import com.vaadin.flow.router.NavigationTrigger;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.theme.lumo.LumoUtility;
+import org.springframework.dao.DataAccessException;
+
+import java.util.stream.Collectors;
+import java.util.stream.Stream;
+
+/** UC-002: Browse veterinarians and their specialties without authentication. */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VetsView extends VerticalLayout {
+    private final transient VetRepository repository;
+    private final Grid<Vet> grid = new Grid<>();
+    private boolean failed;
+
+    public VetsView(VetRepository repository) {
+        this.repository = repository;
+        setSizeFull();
+        H2 heading = new H2("Veterinarians");
+        heading.addClassNames(LumoUtility.Margin.NONE);
+        grid.setSizeFull();
+        grid.setSelectionMode(Grid.SelectionMode.NONE);
+        grid.getElement().setAttribute("aria-label", "Veterinarians");
+        grid.addColumn(Vet::firstName).setHeader("First Name").setKey("firstName").setAutoWidth(true);
+        grid.addColumn(Vet::lastName).setHeader("Last Name").setKey("lastName").setAutoWidth(true);
+        grid.addColumn(vet -> vet.specialties().isEmpty() ? "none" : vet.specialties().stream()
+                .map(specialty -> specialty.name()).collect(Collectors.joining(", ")))
+                .setHeader("Specialties").setKey("specialties").setAutoWidth(true);
+        grid.setItems(this::fetch, query -> count());
+        add(heading, grid);
+        expand(grid);
+    }
+
+    private Stream<Vet> fetch(Query<Vet, Void> query) {
+        if (failed) return Stream.empty();
+        try {
+            return repository.findPage(query.getOffset(), query.getLimit());
+        } catch (DataAccessException exception) {
+            showError(exception);
+            return Stream.empty();
+        }
+    }
+
+    private int count() {
+        if (failed) return 0;
+        try {
+            return repository.count();
+        } catch (DataAccessException exception) {
+            showError(exception);
+            return 0;
+        }
+    }
+
+    private void showError(DataAccessException exception) {
+        failed = true;
+        grid.setVisible(false);
+        UI ui = UI.getCurrent();
+        // Lazy fetches run after navigation too; the router does not catch those automatically.
+        ui.beforeClientResponse(this, context -> ui.getInternals().getRouter()
+                .handleExceptionNavigation(ui, ui.getInternals().getActiveViewLocation(), exception,
+                        NavigationTrigger.PROGRAMMATIC, null));
+    }
+}
